def seed(apps, schema_editor):
    Roadmap = apps.get_model('portal', 'CareerRoadmap')
    College = apps.get_model('portal', 'College')
    Course = apps.get_model('portal', 'Course')
    alias = schema_editor.connection.alias
    for row in DATA:
        Roadmap.objects.using(alias).get_or_create(id=row['id'], defaults={key: value for key, value in row.items() if key != 'id'})
    for college in College.objects.using(alias).all():
        data = dict(college.data or {})
        courses = data.get('courses')
        if not isinstance(courses, list):
            courses = [name.strip() for name in str(data.get('programs', '')).split(',') if name.strip()]
        for entry in courses:
            item = {'name': entry} if isinstance(entry, str) else entry
            if not isinstance(item, dict) or not item.get('name'):
                continue
            Course.objects.using(alias).get_or_create(college=college, name=str(item['name'])[:200], defaults={
                'description': str(item.get('description', ''))[:3000], 'duration': str(item.get('duration', ''))[:100],
                'eligibility': str(item.get('eligibility', ''))[:500],
            })
        if courses:
            data['coursesManaged'] = True
            college.data = data
            college.save(using=alias, update_fields=['data'])

